**Priority Queue Implementation using Binary Min-Heap**
======================================================

```python
class PriorityQueue:
    def __init__(self):
        self.heap = []

    def insert(self, item, priority):
        """Insert item into the priority queue with given priority."""
        self.heap.append((priority, item))
        self._heapify_up(len(self.heap) - 1)

    def delete_min(self):
        """Remove and return the item with the highest priority."""
        if len(self.heap) == 0:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()[1]
        min_item = self.heap[0][1]
        self.heap[0] = self.heap.pop()
        self._heapify_down(0)
        return min_item

    def _heapify_up(self, index):
        """Maintain the heap property by bubbling up the item at the given index."""
        parent_index = (index - 1) // 2
        if index > 0 and self.heap[parent_index][0] > self.heap[index][0]:
            self.heap[parent_index], self.heap[index] = self.heap[index], self.heap[parent_index]
            self._heapify_up(parent_index)

    def _heapify_down(self, index):
        """Maintain the heap property by bubbling down the item at the given index."""
        left_child_index = 2 * index + 1
        right_child_index = 2 * index + 2
        smallest_index = index
        if left_child_index < len(self.heap) and self.heap[left_child_index][0] < self.heap[smallest_index][0]:
            smallest_index = left_child_index
        if right_child_index < len(self.heap) and self.heap[right_child_index][0] < self.heap[smallest_index][0]:
            smallest_index = right_child_index
        if smallest_index != index:
            self.heap[index], self.heap[smallest_index] = self.heap[smallest_index], self.heap[index]
            self._heapify_down(smallest_index)
```
This implementation provides basic operations for a priority queue: `insert` and `delete_min`. The `_heapify_up` and `_heapify_down` methods are used to maintain the heap property after insertion and deletion.
